opId = 0  local function setXRayTargetTransparency(instance, alphaPercent, loopId)     if not instance then return end     if loopId and loopId ~= _G._AmbitiousXRayLoopId then return end     local function apply(obj)         if not obj or not obj.Parent then return end         if obj:IsA("BasePart") then             if _G._AmbitiousXRayOrigTrans[obj] == nil then                 _G._AmbitiousXRayOrigTrans[obj] = obj.Transparency             end             local orig = _G._AmbitiousXRayOrigTrans[obj]             if type(orig) == "number" and orig < 1 then                 local target = orig + (1 - orig) * alphaPercent                 if math.abs(obj.Transparency - target) > 0.01 then obj.Transparency = target end             end         elseif obj:IsA("TextLabel") or obj:IsA("TextButton") then             if _G._AmbitiousXRayOrigTrans[obj] == nil then                 _G._AmbitiousXRayOrigTrans[obj] = { text = obj.TextTransparency, bg = obj.BackgroundTransparency }             end             local orig = _G._AmbitiousXRayOrigTrans[obj]             if type(orig) == "table" then                 if orig.text and orig.text < 1 then                     local t = orig.text + (1 - orig.text) * alphaPercent                     if math.abs(obj.TextTransparency - t) > 0.01 then obj.TextTransparency = t end                 end                 if orig.bg and orig.bg < 1 then                     local t = orig.bg + (1 - orig.bg) * alphaPercent                     if math.abs(obj.BackgroundTransparency - t) > 0.01 then obj.BackgroundTransparency = t end                 end             end         elseif obj:IsA("Frame") or obj:IsA("ScrollingFrame") then             if _G._AmbitiousXRayOrigTrans[obj] == nil then                 _G._AmbitiousXRayOrigTrans[obj] = obj.BackgroundTransparency             end             local orig = _G._AmbitiousXRayOrigTrans[obj]             if type(orig) == "number" and orig < 1 then                 local t = orig + (1 - orig) * alphaPercent                 if math.abs(obj.BackgroundTransparency - t) > 0.01 then obj.BackgroundTransparency = t end             end         elseif obj:IsA("ImageLabel") or obj:IsA("ImageButton") then             if _G._AmbitiousXRayOrigTrans[obj] == nil then                 _G._AmbitiousXRayOrigTrans[obj] = { img = obj.ImageTransparency, bg = obj.BackgroundTransparency }             end             local orig = _G._AmbitiousXRayOrigTrans[obj]             if type(orig) == "table" then                 if orig.img and orig.img < 1 then                     local t = orig.img + (1 - orig.img) * alphaPercent                     if math.abs(obj.ImageTransparency - t) > 0.01 then obj.ImageTransparency = t end                 end             end         elseif obj:IsA("MeshPart") or obj:IsA("UnionOperation") then             if _G._AmbitiousXRayOrigTrans[obj] == nil then                 _G._AmbitiousXRayOrigTrans[obj] = obj.Transparency             end             local orig = _G._AmbitiousXRayOrigTrans[obj]             if type(orig) == "number" and orig < 1 then                 local target = orig + (1 - orig) * alphaPercent                 if math.abs(obj.Transparency - target) > 0.01 then obj.Transparency = target end             end         end     end     apply(instance)     for _, d in ipairs(instance:GetDescendants()) do         if loopId and loopId ~= _G._AmbitiousXRayLoopId then return end         apply(d)     end end  local function trackXRaySubtree(root, alphaPercent, loopId)     if not root then return end     if loopId ~= _G._AmbitiousXRayLoopId then return end     setXRayTargetTransparency(root, alphaPercent, loopId)     table.insert(_G._AmbitiousXRayConns, root.DescendantAdded:Connect(function(obj)         if loopId ~= _G._AmbitiousXRayLoopId then return end         setXRayTargetTransparency(obj, alphaPercent, loopId)     end)) end  local function processPlotXRay(plot, alphaPercent, loopId)     if not plot or loopId ~= _G._AmbitiousXRayLoopId then return end     for _, fname in