P = gP.Unit * 8 end return N.Position + gP end  -- BAT AIMBOT V1 — BloodHounds Bypass engine (integrated for BYPASS BAT BYPASS mode) -- Velocity chase @ 61 | seat = front + on top + body pull | auto swing do local Players = game:GetService("Players") local RunService = game:GetService("RunService") local UIS = game:GetService("UserInputService") local LP = Players.LocalPlayer  local SPEED              = 61 local FRONT_LEAD         = 2.0 local FRONT_LEAD_CLOSE   = 1.25 local SEAT_Y             = 3.25 local SEAT_Y_CLOSE       = 2.85 local BODY_PULL          = 1.05 local CLOSE_DIST         = 9 local ACTIVATE_DISTANCE  = 14 local HIT_CONTACT        = 9.5 local SWING_COOLDOWN     = 0.04 local PREDICT_MIN        = 0.05 local PREDICT_MAX        = 0.16 local MAX_PREDICT        = 110 local ROT_YAW_GAIN       = 320 local ROT_PITCH_GAIN     = 300 local ROT_YAW_MAX        = 36 local ROT_PITCH_MAX      = 30 local PATH_LOOK          = 8 local LIVE_BLEND         = 0.55 local SAMPLE_LERP        = 0.48 local VERT_MATCH         = 0.82  local FLING_CLAMP        = 350 local FLING_HOLD_FRAMES  = 2 local SPOOF_VEL_ABS      = 200 local SPOOF_RATIO        = 0.40 local STANDOFF_DIST      = 2.8 local STANDOFF_HEIGHT    = 4.75 local BYPASS_STANDOFF    = false  local enabled            = false local conn               = nil local prevAutoRotate     = nil local targetPlr          = nil local lastTargetPos      = nil local targetVelocity     = Vector3.zero local smoothedVelocity   = Vector3.zero local velocityHistory    = {} local accelHistory       = {} local previousDirection  = nil local lastActivationTime = 0 local currentPing        = 0.1 local intendedVelocity   = Vector3.zero local wasFlung           = false local flingHoldLeft      = 0 local flingRecoveries    = 0  local function isBatTool(tool)     if not tool or not tool:IsA("Tool") then return false end     local n = tool.Name:lower()     return n:find("bat", 1, true) ~= nil         or n:find("slap", 1, true) ~= nil end  local function findBat()     local char = LP.Character     if not char then return nil end     local eq = char:FindFirstChildOfClass("Tool")     if eq and isBatTool(eq) then return eq end     local bp = LP:FindFirstChildOfClass("Backpack")     if bp then         for _, t in ipairs(bp:GetChildren()) do             if t:IsA("Tool") and isBatTool(t) then return t end         end     end     return nil end  local function selectTarget(root)     if targetPlr and targetPlr.Parent and targetPlr.Character then         local r = targetPlr.Character:FindFirstChild("HumanoidRootPart")         local h = targetPlr.Character:FindFirstChildOfClass("Humanoid")         if r and h and h.Health > 0 then             return targetPlr, r         end     end     local bestPlr, bestRoot, bestD = nil, nil, math.huge     for _, p in ipairs(Players:GetPlayers()) do         if p ~= LP and p.Character then             local r = p.Character:FindFirstChild("HumanoidRootPart")             local h = p.Character:FindFirstChildOfClass("Humanoid")             if r and h and h.Health > 0 then                 local d = (root.Position - r.Position).Magnitude                 if d < bestD then                     bestD, bestPlr, bestRoot = d, p, r                 end             end         end     end     targetPlr = bestPlr     return bestPlr, bestRoot end  local function push(hist, v, maxn)     table.insert(hist, v)     if #hist > maxn then table.remove(hist, 1) end end  local function avg(hist)     if #hist == 0 then return Vector3.zero end     local t = Vector3.zero     for _, v in ipairs(hist) do t = t + v end     return t / #hist end  local function samplePing()     local ok, v = pcall(function()         return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()     end)     if ok and type(v) == "number" then         currentPing = math.clamp(v / 1000, 0.03, 0.28)     end end  local function stop()     enabled = false     if conn then pcall(function() conn:Disconnect() end); conn = nil end     local char = LP.Character     local hum = char and char:FindFirstChildOfClass("Humanoid")     local root = char and char:FindFirstChild("HumanoidRootPart")     if hum and prevAutoRotate ~= nil then         hum.AutoRotate = prevAutoRotate     end     prevAutoRotate = nil     if root then         root.AssemblyAngularVelocity = Vector3.zero     end     targetPlr = nil     lastTargetPos = nil     targetVelocity = Vector3.zero     smoothedVelocity = Vector3.zero     velocityHistory = {}     accelHistory = {}     previousDirection = nil     intendedVelocity = Vector3.zero     wasFlung = false     flingHoldLeft = 0 end  local function start()     if conn then return end     local char = LP.Character     local humanoid = char and char:FindFirstChildOfClass("Humanoid")     local root = char and char:FindFirstChild("HumanoidRootPart")     if not humanoid or not root or humanoid.Health <= 0 then         return     end      enabled = true     prevAutoRotate = humanoid.AutoRotate     humanoid.AutoRotate = false      local bat = findBat()     if bat and bat.Parent ~= char and not char:FindFirstChildOfClass("Tool") then         pcall(function() humanoid:EquipTool(bat) end)     end      conn = RunService.RenderStepped:Connect(function(dt)         if not enabled then stop(); return end          local currentChar = LP.Character         local currentRoot = currentChar and currentChar:FindFirstChild("HumanoidRootPart")         local currentHum  = currentChar and currentChar:FindFirstChildOfClass("Humanoid")         if not currentRoot or not currentHum or currentHum.Health <= 0 then return end         currentHum.AutoRotate = false         root, humanoid = currentRoot, currentHum          local equipped = currentChar:FindFirstChildOfClass("Tool")         bat = (equipped and isBatTool(equipped)) and equipped or nil         if not bat then             bat = findBat()             if bat and bat.Parent ~= currentChar then                 pcall(function() currentHum:EquipTool(bat) end)                 equipped = currentChar:FindFirstChildOfClass("Tool")                 bat = (equipped and isBatTool(equipped)) and equipped or nil             end         end          local plr, targetRoot = selectTarget(root)         if not targetRoot then             root.AssemblyLinearVelocity = Vector3.new(                 root.AssemblyLinearVelocity.X * 0.7,                 root.AssemblyLinearVelocity.Y,                 root.AssemblyLinearVelocity.Z * 0.7             )             root.AssemblyAngularVelocity = Vector3.zero             return         end          local now       = tick()         local targetPos = targetRoot.Position         local targetCF  = targetRoot.CFrame         local liveDist  = (targetPos - root.Position).Magnitude         local liveVel   = targetRoot.AssemblyLinearVelocity         local safeDt    = math.max(dt, 1/240)          local rawVel = liveVel         if lastTargetPos then             local measured = (targetPos - lastTargetPos) / safeDt             if measured.Magnitude > MAX_PREDICT then                 measured = measured.Unit * MAX_PREDICT             end              local spoofed = false             if liveVel.Magnitude > SPOOF_VEL_ABS then                 if measured.Magnitude < liveVel.Magnitude * SPOOF_RATIO then                     spoofed = true                 end             end             if spoofed then                 rawVel = measured             else                 rawVel = measured:Lerp(liveVel, LIVE_BLEND)             end              if rawVel.Magnitude > MAX_PREDICT then                 rawVel = rawVel.Unit * MAX_PREDICT             end             push(accelHistory, (rawVel - targetVelocity) / safeDt, 6)             push(velocityHistory, rawVel, 12)             targetVelocity = rawVel             smoothedVelocity = smoothedVelocity:Lerp(rawVel, SAMPLE_LERP)         else             targetVelocity = liveVel             smoothedVelocity = liveVel         end         lastTargetPos = targetPos          local predictedVelocity = smoothedVelocity         if #velocityHistory > 2 then             predictedVelocity = avg(velocityHistory):Lerp(smoothedVelocity, 0.45)         end          local horizVel = Vector3.new(predictedVelocity.X, 0, predictedVelocity.Z)         if horizVel.Magnitude > 2.5 then             previousDirection = horizVel.Unit         end          local predT = math.clamp(horizVel.Magnitude / 125, PREDICT_MIN, PREDICT_MAX)         predT = math.clamp(predT + currentPing * 0.5, PREDICT_MIN, PREDICT_MAX + 0.08)         local accel = avg(accelHistory)         local predicted = targetPos             + predictedVelocity * predT             + accel * 0.35 * (predT * predT * 0.5)          local frontDir         if horizVel.Magnitude > 2.0 then             frontDir = horizVel.Unit         else             local look = Vector3.new(targetCF.LookVector.X, 0, targetCF.LookVector.Z)             if look.Magnitude > 0.1 then                 frontDir = look.Unit             else                 local to = Vector3.new(predicted.X - root.Position.X, 0, predicted.Z - root.Position.Z)                 frontDir = to.Magnitude > 0.1 and to.Unit or Vector3.new(0, 0, -1)             end         end          local seat         if BYPASS_STANDOFF then             local aimPoint = predicted + frontDir * FRONT_LEAD + Vector3.new(0, SEAT_Y, 0)             local toAim = aimPoint - root.Position             local unit = toAim.Magnitude > 0.01 and toAim.Unit or Vector3.zero             seat = aimPoint - unit * STANDOFF_DIST + Vector3.new(0, STANDOFF_HEIGHT, 0)         else             local close    = liveDist < CLOSE_DIST             local frontLead = close and FRONT_LEAD_CLOSE or FRONT_LEAD             local seatY     = close and SEAT_Y_CLOSE     or SEAT_Y             local toBody    = Vector3.new(predicted.X - root.Position.X, 0, predicted.Z - root.Position.Z)             local bodyPull  = toBody.Magnitude > 0.1 and toBody.Unit * BODY_PULL or Vector3.zero             seat = predicted + frontDir * frontLead + bodyPull + Vector3.new(0, seatY, 0)         end          local chaseDelta = seat - root.Position         local chaseFlat  = Vector3.new(chaseDelta.X, 0, chaseDelta.Z)          local faceDelta         if horizVel.Magnitude > 2.5 then             faceDelta = (predicted + frontDir * PATH_LOOK + Vector3.new(0, 1.2, 0)) - root.Position         else             faceDelta = chaseDelta         end         local faceFlat = Vector3.new(faceDelta.X, 0, faceDelta.Z)         if faceFlat.Magnitude > 0.08 then             local yawError = (math.deg(math.atan2(-faceFlat.X, -faceFlat.Z)) - root.Orientation.Y + 180) % 360 - 180             local pitchError = (math.deg(math.atan2(faceDelta.Y, math.max(faceFlat.Magnitude, 0.01))) - root.Orientation.X + 180) % 360 - 180             local yaw   = math.clamp(math.rad(yawError)   * ROT_YAW_GAIN,   -ROT_YAW_MAX,   ROT_YAW_MAX)             local pitch = math.clamp(math.rad(pitchError) * ROT_PITCH_GAIN, -ROT_PITCH_MAX, ROT_PITCH_MAX)             local facingYaw = math.rad(root.Orientation.Y)             local facing    = Vector3.new(math.cos(facingYaw), 0, -math.sin(facingYaw))             root.AssemblyAngularVelocity = Vector3.new(0, yaw, 0) + facing * pitch         else             root.AssemblyAngularVelocity = Vector3.zero         end          local matchVel = horizVel         if matchVel.Magnitude > SPEED then matchVel = matchVel.Unit * SPEED end         local toward         if chaseFlat.Magnitude > 0.2 then             toward = chaseFlat.Unit * SPEED         else             toward = frontDir * SPEED         end         local horizontal = toward:Lerp(matchVel, 0.32)         if horizontal.Magnitude > 0.05 then             if chaseFlat.Magnitude > 0.2 then                 horizontal = horizontal.Unit * SPEED             elseif horizontal.Magnitude > SPEED then                 horizontal = horizontal.Unit * SPEED             end         end          local verticalY         if math.abs(chaseDelta.Y) > 0.12 then             verticalY = math.clamp(math.sign(chaseDelta.Y) * SPEED + predictedVelocity.Y * VERT_MATCH, -SPEED, SPEED)         else             verticalY = predictedVelocity.Y * VERT_MATCH - 1.2         end          intendedVelocity = Vector3.new(horizontal.X, verticalY, horizontal.Z)         root.AssemblyLinearVelocity = intendedVelocity          if chaseFlat.Magnitude > 0.3 then             pcall(function() humanoid:Move(chaseFlat.Unit, false) end)         end          if bat and bat.Parent == currentChar and liveDist <= ACTIVATE_DISTANCE             and (now - lastActivationTime) >= SWING_COOLDOWN then             pcall(function() bat:Activate() end)             pcall(function()                 for _, d in ipairs(bat:GetDescendants()) do                     if d:IsA("RemoteEvent") then                         pcall(function() d:FireServer() end)                         break                     end                 end             end)             lastActivationTime = now         end          local curVel   = root.AssemblyLinearVelocity         local horizMag = math.sqrt(curVel.X * curVel.X + curVel.Z * curVel.Z)          if horizMag > FLING_CLAMP then             root.AssemblyLinearVelocity = intendedVelocity             root.AssemblyAngularVelocity = Vector3.zero             wasFlung = true             flingHoldLeft = FLING_HOLD_FRAMES             flingRecoveries = flingRecoveries + 1         elseif wasFlung then             if flingHoldLeft > 0 then                 root.AssemblyLinearVelocity = intendedVelocity                 flingHoldLeft = flingHoldLeft - 1             else                 wasFlung = false             end         end          _G._aimbotTarget = targetRoot         _G._aimbotTargetPlr = plr     end) end  task.spawn(function()     while true do         pcall(samplePing)         task.wait(0.5)     end end)  LP.CharacterAdded:Connect(function()     if enabled then         local old = enabled         stop()         task.wait(0.5)         if old then start() end     end end)  _G.BatAimbotV1 = {     start    = start,     stop     = stop,     toggle   = function() if enabled then stop() else start() end return enabled end,     isEnabled = function() return enabled end,     setBypass = function(on)         BYPASS_STANDOFF = on == true         return BYPASS_STANDOFF     end,     isBypass  = function() return BYPASS_STANDOFF end,     getRecoveries = function() return flingRecoveries end,     resetRecoveries = function() flingRecoveries = 0 end, } end  local AIMBOT_ATTACHMENT_NAME = "CandyAimbotMoveAttachment" local AIMBOT_MOVER_NAME = "CandyAimbotMoveVelocity" local AIMBOT_MIN_FORCE = 1000000 local AIMBOT_MAX_FORCE = 50000000 local function gQ0(V) local mover = V and V:FindFirstChild(AIMBOT_MOVER_NAME) if mover and mover:IsA("LinearVelocity") then mover:Destroy() end local attachment = V and V:FindFirstChild(AIMBOT_ATTACHMENT_NAME) if attachment and attachment:IsA("Attachment") then attachment:Destroy() end end _G._CandyClearAimbotMover = function() local bz = g.Character gQ0(bz and bz:FindFirstChild("HumanoidRootPart")) end local function gQ1(V) local mover = V:FindFirstChild(AIMBOT_MOVER_NAME) if mover and not mover:IsA("LinearVelocity") then mover:Destroy() mover = nil end local attachment = V:FindFirstChild(AIMBOT_ATTACHMENT_NAME) if attachment and not attachment:IsA("Attachment") then attachment:Destroy() attachment = nil end if not attachment then attachment = Instance.new("Attachment") attachment.Name = AIMBOT_ATTACHMENT_NAME attachment.Parent = V end if not mover then mover = Instance.new("LinearVelocity") mover.Name = AIMBOT_MOVER_NAME mover.Attachment0 = attachment mover.RelativeTo = Enum.ActuatorRelativeTo.World mover.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector mover.ForceLimitsEnabled = true mover.ForceLimitMode = Enum.ForceLimitMode.PerAxis mover.VectorVelocity = V.AssemblyLinearVelocity mover.Parent = V end return mover end local function gQ2(V, desired, speed, deltaTime) local mover = gQ1(V) local force = math.clamp( V.AssemblyMass * math.max((tonumber(speed) or 0) * 220, 6000), AIMBOT_MIN_FORCE, AIMBOT_MAX_FORCE ) mover.Enabled = true mover.MaxAxesForce = Vector3.new(force, force, force) local blend = 1 - math.exp(-math.max(deltaTime or (1 / 60), 0) * 26) mover.VectorVelocity = mover.VectorVelocity:Lerp(desired, blend) end local ZBAT_SPEED = 56 local ZBAT_VERT_SPEED = 52 local ZBAT_DIST = -2.8 local ZBAT_HEIGHT = 4.75 local ZBAT_VERT_OFFSET = 1 local ZBAT_TURN_SPEED = 285 local ZBAT_MAX_TURN_RATE = 28 local function aimbotUsesNewLoop() return a1.antiMode ~= true end local function aimbotGateBlocked() return _G._CandySafeGateBlocked ~= nil and _G._CandySafeGateBlocked() == true end local function gQ() _G._AdaptTPMirrorEnabled = true if ad.aimbot then ad.aimbot:Disconnect() ad.aimbot = nil end if ad.aimbotNew then ad.aimbotNew:Disconnect() ad.aimbotNew = nil end _G._adaptBatPred = {} _G._AdaptNormalAimbot = _G._AdaptNormalAimbot or { target = nil, swingCooldown = false } local aimbotState = _G._AdaptNormalAimbot aimbotState.target = nil aimbotState.swingCooldown = false aimbotState.equipped = false ad.aimbotNewEquipped = false ad.aimbotSwingCooldown = false local hum0 = g.Character and g.Character:FindFirstChildOfClass("Humanoid") if hum0 then hum0.AutoRotate = false end -- BYPASS BAT BYPASS uses BatAimbotV1 (BloodHounds engine) if a1.antiMode then pcall(function() if _G.BatAimbotV1 and _G.BatAimbotV1.stop then _G.BatAimbotV1.stop() end end) pcall(function() if _G.BatAimbotV1 and _G.BatAimbotV1.start then _G.BatAimbotV1.start() end end) return end  ad.aimbot = d.RenderStepped:Connect(LPH_NO_VIRTUALIZE(function() if not a1.aimbot or aimbotUsesNewLoop() then return end if aimbotGateBlocked() then pcall(_G._CandyClearAimbotMover) return end local bz = g.Character if not bz then return end local V = bz:FindFirstChild("HumanoidRootPart") if not V then return end local cY = bz:FindFirstChildOfClass("Humanoid") if not cY then return end local gR = bz:FindFirstChildO