feMode:_disable(action) local entry = self.Actions[action] if entry then pcall(entry.set, false) end end function SafeMode:Request(action, wantsOn) local entry = self.Actions[action] if not entry then return false, "UNBOUND ACTION" end if wantsOn ~= true then self:_disable(action) return true end local reason = self:GetBlockReason() if reason then self:_disable(action) return false, reason end for o, other in ipairs(entry.conflicts) do self:_disable(other) end entry.set(true) return true end function SafeMode:Toggle(action) local entry = self.Actions[action] return entry and self:Request(action, not entry.get()) or false end local safeDimmed = false local function safeApplyDim(on) if safeDimmed == on then return end safeDimmed = on for o, cS in ipairs(safeGuarded) do local h_ = safeToggleRef(cS) if h_ and h_.Card then h_.Card.BackgroundTransparency = on and 0.5 or 0.03 end end end local safeSpeedDimmed = false local function safeApplySpeedDim(on) if safeSpeedDimmed == on then return end safeSpeedDimmed = on local cards = _G._CandySpeedCards if type(cards) ~= "table" then return end for o, nh in ipairs(cards) do if nh.card and (nh.mode == "Normal" or nh.mode == "Lagger") then nh.card.BackgroundTransparency = on and 0.5 or 0.03 end end end function SafeMode:Evaluate() local state = self._state local countdown = self:IsRoundCountdownActive() local holding = self:IsHoldingBrainrot() state.countdown, state.holding = countdown, holding if not self.Enabled then return end local reason = self:GetBlockReason() safeApplyDim(reason ~= nil) safeApplySpeedDim(holding) if not reason then return end for action, entry in pairs(self.Actions) do if entry.get() then self:_disable(action) end end end function SafeMode:SetEnabled(enabled) self.Enabled = enabled == true if not self.Enabled then safeApplyDim(false) safeApplySpeedDim(false) else self._state.countdown, self._state.holding = false, false self:Evaluate() end self:_refreshToggleUi() end function SafeMode:_refreshToggleUi() if self.Ref and self.Ref.SetVisual then pcall(self.Ref.SetVisual, self.Enabled) end end function SafeMode:_watchCarryState() local function evaluateSoon() task.defer(function() if SafeMode._running and SafeMode.Enabled then pcall(function() SafeMode:Evaluate() end) end end) end for marker in pairs(CARRY_MARKERS) do self._connections["player_" .. marker] = g:GetAttributeChangedSignal(marker):Connect(evaluateSoon) end local function watchCharacter(character) for key, connection in pairs(self._connections) do if key:sub(1, 5) == "char_" then safeDisconnect(connection) self._connections[key] = nil end end if not character then return end for marker in pairs(CARRY_MARKERS) do self._connections["char_attr_" .. marker] = character:GetAttributeChangedSignal(marker):Connect(evaluateSoon) end self._connections.char_added = character.DescendantAdded:Connect(LPH_NO_VIRTUALIZE(function(item) if item:IsA("Tool") or CARRY_MARKERS[item.Name] then evaluateSoon() end end)) self._connections.char_removed = character.DescendantRemoving:Connect(function(item) if item:IsA("Tool") or CARRY_MARKERS[item.Name] then evaluateSoon() end end) end self._connections.character = g.CharacterAdded:Connect(function(character) watchCharacter(character) evaluateSoon() end) watchCharacter(g.Character) end function SafeMode:Start() if self._running then return self end self._running = true self:_watchCarryState() self._connections.monitor = d.Heartbeat:Connect(LPH_NO_VIRTUALIZE(function() if not SafeMode.Enabled or os.clock() - SafeMode._lastCheck < 0.1 then return end SafeMode._lastCheck = os.clock() pcall(function() SafeMode:Evaluate() end) end)) if self.Enabled then self:Evaluate() end return self end function SafeMode:Destroy() self._running = false for key, connection in pairs(self._connections) do safeDisconnect(connection) self._connections[key] = nil end end for o, cS in ipairs(safeGuarded) do SafeMode:BindAction(cS, function() local h_ = safeToggleRef(cS) return (h_ and h_.Get and h_.Get()) == true